class Solution {
public:
    string largestGoodInteger(string num) {
        bool found = false;
        char bestDigit = '0';
        int n = (int)num.size();
        for (int i = 0; i + 2 < n; i++) {
            if (num[i] == num[i+1] && num[i+1] == num[i+2]) {
                if (!found || num[i] > bestDigit) {
                    bestDigit = num[i];
                    found = true;
                }
            }
        }
        if (!found) return "";
        return string(3, bestDigit);
    }
};
